fn cell(rows: List[Str], r: Int, c: Int) -> Str {
  return rows.get_or(r, "").slice(c, c + 1)
}

fn row_cells(rows: List[Str], r: Int) -> List[Str] {
  return range(0, 9).map(fn(c) => cell(rows: rows, r: r, c: c))
}

fn col_cells(rows: List[Str], c: Int) -> List[Str] {
  return range(0, 9).map(fn(r) => cell(rows: rows, r: r, c: c))
}

fn box_cells(rows: List[Str], b: Int) -> List[Str] {
  let top = (b / 3) * 3
  let left = (b % 3) * 3
  return range(0, 9).map(fn(k) => cell(rows: rows, r: top + k / 3, c: left + k % 3))
}

fn no_repeat(cells: List[Str]) -> Bool {
  let filled = cells.filter(fn(x) => x != ".")
  return filled.unique().len() == filled.len()
}

fn shape_ok(rows: List[Str]) -> Bool {
  if rows.len() != 9 {
    return false
  }
  return rows.all(fn(r) => (r.len() == 9) and r.chars().all(fn(ch) => "123456789.".contains(ch)))
}

pub fn sudoku(rows: List[Str]) -> Bool {
  if not shape_ok(rows) {
    return false
  }
  let rows_ok = range(0, 9).all(fn(i) => no_repeat(row_cells(rows: rows, r: i)))
  let cols_ok = range(0, 9).all(fn(i) => no_repeat(col_cells(rows: rows, c: i)))
  let boxes_ok = range(0, 9).all(fn(i) => no_repeat(box_cells(rows: rows, b: i)))
  return rows_ok and cols_ok and boxes_ok
}
